// Stale-build guard. The moderator's device resolves every phase (spec-2b D5), so a
// moderator tab opened before a deploy keeps running the OLD game rules until it reloads:
// the app never re-downloads its JavaScript on its own. (Live bug, 2026-10-28: a tab from
// before the final Granny rule resolved a Granny night with the old "Granny dies too" rule.)
//
// BUILD_ID is baked into this bundle at build time, and /version.json (app/version.json/
// route.ts) is generated by the same build, so it always reports the build that is live
// NOW. Before resolving, the moderator's tab compares the two and refuses if it's older.

/** This bundle's build: the deployed git commit on Vercel, "local" everywhere else. */
export const BUILD_ID = process.env.NEXT_PUBLIC_BUILD_ID ?? "local";

/**
 * True unless the server reports a different build than this tab is running. If the
 * check itself can't be made (offline, slow, blocked), it returns true: an unreachable
 * version file must never block a game in progress.
 */
export async function isLatestBuild(): Promise<boolean> {
  try {
    const res = await fetch("/version.json", { cache: "no-store", signal: AbortSignal.timeout(5000) });
    if (!res.ok) return true;
    const { buildId } = (await res.json()) as { buildId?: string };
    return !buildId || buildId === BUILD_ID;
  } catch {
    return true;
  }
}
